solution.code:
export const eleccion = {
  necesidades: {
    casosTecnicos24x7: true,
    comprobacionesCompletasTrustedAdvisor: true,
    tamDesignado: false,
  },
  planElegido: "BUSINESS_PLUS",
  planes: [
    { plan: "BASIC", casosTecnicos24x7: false, comprobacionesCompletasTrustedAdvisor: false, tamDesignado: false },
    { plan: "BUSINESS_PLUS", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: false },
    { plan: "ENTERPRISE", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: true },
    { plan: "UNIFIED_OPERATIONS", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: true },
  ],
};

spec.code:
const plan = eleccion.planes.find((p) => p.plan === eleccion.planElegido);
assert.ok(plan, "el plan elegido debe existir en la lista de planes");
if (eleccion.necesidades.casosTecnicos24x7) {
  assert.strictEqual(plan.casosTecnicos24x7, true, "debe incluir casos técnicos 24x7");
}
if (eleccion.necesidades.comprobacionesCompletasTrustedAdvisor) {
  assert.strictEqual(plan.comprobacionesCompletasTrustedAdvisor, true, "debe incluir todas las comprobaciones de Trusted Advisor");
}
if (eleccion.necesidades.tamDesignado) {
  assert.strictEqual(plan.tamDesignado, true, "debe incluir un TAM designado");
}

const cubre = (p: (typeof eleccion.planes)[number]): boolean =>
  (!eleccion.necesidades.casosTecnicos24x7 || p.casosTecnicos24x7) &&
  (!eleccion.necesidades.comprobacionesCompletasTrustedAdvisor || p.comprobacionesCompletasTrustedAdvisor) &&
  (!eleccion.necesidades.tamDesignado || p.tamDesignado);
const primero = eleccion.planes.find(cubre);
assert.ok(primero, "algún plan debe cubrir las necesidades");
assert.strictEqual(eleccion.planElegido, primero.plan);

assert.deepStrictEqual(eleccion.necesidades, {
  casosTecnicos24x7: true,
  comprobacionesCompletasTrustedAdvisor: true,
  tamDesignado: false,
});

assert.deepStrictEqual(eleccion.planes, [
  { plan: "BASIC", casosTecnicos24x7: false, comprobacionesCompletasTrustedAdvisor: false, tamDesignado: false },
  { plan: "BUSINESS_PLUS", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: false },
  { plan: "ENTERPRISE", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: true },
  { plan: "UNIFIED_OPERATIONS", casosTecnicos24x7: true, comprobacionesCompletasTrustedAdvisor: true, tamDesignado: true },
]);

exercises.starterCode:
// Decide a qué comprobaciones de Trusted Advisor accede un plan. Corrige su defecto principal.
export type Plan = "BASIC" | "BUSINESS_PLUS" | "ENTERPRISE" | "UNIFIED_OPERATIONS";
export type Categoria = "SERVICE_LIMITS" | "SECURITY" | "FAULT_TOLERANCE";
export type Acceso = "TODAS" | "SELECCIONADAS";

export function comprobacionesAccesibles(plan: Plan, categoria: Categoria): Acceso {
  if (plan !== "BASIC") {
    return "TODAS";
  }
  return categoria === "SECURITY" ? "SELECCIONADAS" : "TODAS";
}

solution.code:
export type Plan = "BASIC" | "BUSINESS_PLUS" | "ENTERPRISE" | "UNIFIED_OPERATIONS";
export type Categoria = "SERVICE_LIMITS" | "SECURITY" | "FAULT_TOLERANCE";
export type Acceso = "TODAS" | "SELECCIONADAS";

export function comprobacionesAccesibles(plan: Plan, categoria: Categoria): Acceso {
  if (plan !== "BASIC") {
    return "TODAS";
  }
  return categoria === "SERVICE_LIMITS" ? "TODAS" : "SELECCIONADAS";
}

spec.code:
const planes: Plan[] = ["BUSINESS_PLUS", "ENTERPRISE", "UNIFIED_OPERATIONS"];
const categorias: Categoria[] = ["SERVICE_LIMITS", "SECURITY", "FAULT_TOLERANCE"];
for (const plan of planes) {
  for (const categoria of categorias) {
    assert.strictEqual(comprobacionesAccesibles(plan, categoria), "TODAS", plan + " / " + categoria);
  }
}
